7	/// Wraps `package:connectivity_plus`'s `Connectivity` behind the
8	/// [ConnectivityWatcher] port — a `get_it` lazy singleton
9	/// (`chat_injection.dart`), mirroring `RecordMicRecorder`'s own
10	/// "wrap-the-real-plugin" shape.
11	///
12	/// [watch] emits the device's *current* status as soon as it's known
13	/// (via [Connectivity.checkConnectivity]), then every subsequent change
14	/// (via [Connectivity.onConnectivityChanged]) — so a caller that starts
15	/// out already offline (e.g. `ChatCubit`'s own constructor-time
16	/// subscription) learns that right away, not only once the status
17	/// changes for the first time.
18	///
19	/// Review finding: the live [Connectivity.onConnectivityChanged]
20	/// subscription starts immediately, never gated behind the initial
21	/// [Connectivity.checkConnectivity] read — a hang (not just a throw) on
22	/// that one platform-channel call must never block connectivity watching
23	/// from starting at all for the rest of the session. The initial read is
24	/// purely a best-effort *seed* value: it's only ever used if it resolves
25	/// (successfully or not) before the live subscription has already
26	/// delivered its own first event, and any failure from it (including a
27	/// never-resolving hang, which simply never seeds anything) is silently
28	/// ignored rather than ending the stream.
29	class ConnectivityPlusWatcher implements ConnectivityWatcher {
30	  ConnectivityPlusWatcher({Connectivity? connectivity})
31	    : _connectivity = connectivity ?? Connectivity();
32	
33	  final Connectivity _connectivity;
34	
35	  @override
36	  Stream<bool> watch() {
37	    final controller = StreamController<bool>();
38	    var liveEventDelivered = false;
39	
40	    // Guarded (RNF09) the same way the seed read below is: a mocked/
41	    // misbehaving `onConnectivityChanged` getter or `.listen()` throwing
42	    // synchronously must never escape `watch()` itself.
43	    try {
44	      final liveSubscription = _connectivity.onConnectivityChanged.listen(
45	        (results) {
46	          liveEventDelivered = true;
47	          controller.add(_isOnline(results));
48	        },
49	        onError: controller.addError,
50	        onDone: controller.close,
51	      );
52	      controller.onCancel = liveSubscription.cancel;
53	    } catch (_) {
54	      // Best-effort only — the seed read below still gets a chance to
55	      // deliver at least one reading.
56	    }
57	
58	    // Fire-and-forget: never awaited, so a hang here can't delay (let
59	    // alone block) the live subscription started above — it only ever
60	    // reaches into the controller if it resolves before any live event
61	    // already has. Wrapped in its own try/catch (RNF09) rather than
62	    // relying solely on `Future.then`'s own error channel — a mocked/
63	    // misbehaving `checkConnectivity()` throwing synchronously, instead
64	    // of returning a rejected `Future`, must never escape [watch] itself.
65	    unawaited(_seedFromInitialCheck(controller, () => liveEventDelivered));
66	
67	    return controller.stream;
68	  }
69	
70	  Future<void> _seedFromInitialCheck(
71	    StreamController<bool> controller,
72	    bool Function() liveEventAlreadyDelivered,
73	  ) async {
74	    try {
75	      final results = await _connectivity.checkConnectivity();
76	      if (!liveEventAlreadyDelivered() && !controller.isClosed) {
77	        controller.add(_isOnline(results));
78	      }
79	    } catch (_) {
80	      // Best-effort seed only — see this class's own doc above.
81	    }
82	  }
83	
84	  /// `connectivity_plus`'s own contract: the emitted list is never empty,
85	  /// and [ConnectivityResult.none] only ever appears alone (the package's
86	  /// own doc on `Connectivity.onConnectivityChanged`) — so "online" is
87	  /// simply "not exactly `[none]`", checked the permissive way (`any`
88	  /// non-`none` entry) rather than relying on that exact shape.
89	  static bool _isOnline(List<ConnectivityResult> results) =>
90	      results.any((result) => result != ConnectivityResult.none);
91	}
